query:
SELECT DISTINCT ?item ?matchedLabel ?en ?zh ?description ?kind WHERE {
          VALUES ?matchedLabel { "atomic operation"@en "atomicity"@en "availability"@en "bandwidth"@en "cache"@en "cache coherence"@en "cache hit"@en "cache miss"@en "client-server model"@en "column"@en "computer network"@en "condition variable"@en "consensus"@en "consistency"@en "critical section"@en "database"@en "datagram"@en "deadlock"@en "denormalization"@en "device driver"@en "direct memory access"@en "distributed computing"@en "distributed system"@en "durability"@en "eventual consistency"@en "fault tolerance"@en "field"@en "file descriptor"@en "file system"@en "foreign key"@en "index"@en "inner join"@en "inode"@en "input/output"@en "interrupt"@en "isolation"@en "join"@en "latency"@en "leader election"@en "linearizability"@en "livelock"@en "load balancing"@en "materialized view"@en "memory barrier"@en "message passing"@en "mutex"@en "network partition"@en "normalization"@en "outer join"@en "packet"@en "page fault"@en "page table"@en "paging"@en "partitioning"@en "peer-to-peer"@en "primary key"@en "protocol"@en "query"@en "query optimization"@en "quorum"@en "race condition"@en "relational database"@en "remote procedure call"@en "replica"@en "replication"@en "round-trip time"@en "row"@en "scalability"@en "semaphore"@en "serializability"@en "sharding"@en "starvation"@en "stored procedure"@en "strong consistency"@en "table"@en "throughput"@en "transaction"@en "translation lookaside buffer"@en "trigger"@en "virtual memory"@en }
          ?item (rdfs:label|skos:altLabel) ?matchedLabel.
          OPTIONAL { ?item rdfs:label ?en. FILTER(LANG(?en)="en") }
          OPTIONAL { ?item rdfs:label ?zh. FILTER(LANG(?zh) IN ("zh-hans","zh-cn","zh")) }
          OPTIONAL { ?item schema:description ?description. FILTER(LANG(?description)="en") }
          OPTIONAL { ?item wdt:P31 ?kind }
        }
